/**
 * Canonical list of raw protobuf documentation files generated by `buf generate`.
 *
 * The order matters: split-connectrpc-docs preserves this order through Map
 * insertion, affecting the section order in rendered output. Trim uses a Set
 * and does not depend on order.
 *
 * Both codegen-proto scripts import this list to avoid silent drift when a new
 * protobuf package is added, removed, or renamed.
 */
export const CONNECTRPC_RAW_MDX_FILES = [
  'apps/docs-website/src/generated/connectrpc-api/auth.raw.mdx',
  'apps/docs-website/src/generated/connectrpc-api/discovery.raw.mdx',
  'apps/docs-website/src/generated/connectrpc-api/api.raw.mdx',
  'apps/docs-website/src/generated/connectrpc-api/admin.raw.mdx',
  'apps/docs-website/src/generated/connectrpc-api/realtime.raw.mdx'
];
